        "detail": "据八闽国资消息，泉州城建集团有限公司近日发布2026年第一批社会招聘公告，计划面向社会为其权属企业公开招聘工作人员22名。报名时间为即日起至2026年4月15日17:30，采用线上报名方式。 公告对行政（事业）身份干部录用后的身份转换、境外学历认证、专业目录外专业认定等事项作出了特别说明。同时，公告明确了六类不得参加应聘的情形，包括存在《公司法》规定情形、受...",
        "content": "据八闽国资消息，泉州城建集团有限公司近日发布2026年第一批社会招聘公告，计划面向社会为其权属企业公开招聘工作人员22名。报名时间为即日起至2026年4月15日17:30，采用线上报名方式。 公告对行政（事业）身份干部录用后的身份转换、境外学历认证、专业目录外专业认定等事项作出了特别说明。同时，公告明确了六类不得参加应聘的情形，包括存在《公司法》规定情形、受过刑事处罚、被列为失信被执行人等情况。 2. 岗位序号6-20：考核包括笔试和面试。笔试成绩占总成绩40%，面试占60%。各环节同样设合格线，并按成绩比例确定晋级名单。 笔试、面谈及面试的具体时间将通过泉州城建集团微信公众号另行通知。 录用人员实行聘任制，签订3年期劳动合同，试用期6个月。 公告提醒应聘者须对报名信息真实性负责，弄虚作假者将受到相应处理。本次招聘不指定考试辅导用书，不举办也不委托任何机构举办辅导培训班。 招聘相关信息将通过泉州城建集团网站及微信公众号发布。 原文：泉州城建集团2026年第一批社会招聘（来源：八闽国资）"
